{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_mix_score AS WITH alloc_mix AS ( SELECT branch_code, order_date, UPPER(category) AS category, COALESCE(UPPER(style), \'SNITCH\') AS style, COALESCE(UPPER(meta1), \'N/A\') AS meta1, COALESCE(UPPER(meta2), \'N/A\') AS meta2, COALESCE(UPPER(meta3), \'N/A\') AS meta3, COUNT(DISTINCT sku_group) AS actual_options FROM snitch_db.maplemonk.fresh_allocation_tagged WHERE category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), alloc_totals AS ( SELECT branch_code, order_date, SUM(actual_options) AS day_total_options, COUNT(*) AS day_total_combos FROM alloc_mix GROUP BY 1,2 ), target_mix AS ( SELECT s.branch_code, s.order_date, s.category, s.style, s.meta1, s.meta2, s.meta3, s.sales_mix_blended_pct AS sales_mix_target_pct, z.zone AS store_zone, CASE WHEN z.zone = \'NORTH\' THEN \'SOUTH\' WHEN z.zone = \'SOUTH\' THEN \'NORTH\' ELSE NULL END AS other_zone FROM snitch_db.maplemonk.fresh_sales_mix_reference s LEFT JOIN snitch_db.maplemonk.store_zone_map z ON s.branch_code = z.branch_code ), joined_all AS ( SELECT COALESCE(a.branch_code, t.branch_code) AS branch_code, COALESCE(a.order_date, t.order_date) AS order_date, COALESCE(a.category, t.category) AS category, COALESCE(a.style, t.style) AS style, COALESCE(a.meta1, t.meta1) AS meta1, COALESCE(a.meta2, t.meta2) AS meta2, COALESCE(a.meta3, t.meta3) AS meta3, COALESCE(a.actual_options, 0) AS actual_options, COALESCE(t.sales_mix_target_pct, 0) AS sales_mix_target_pct, t.store_zone, t.other_zone FROM alloc_mix a FULL OUTER JOIN target_mix t ON a.branch_code = t.branch_code AND a.order_date = t.order_date AND a.category = t.category AND a.style = t.style AND a.meta1 = t.meta1 AND a.meta2 = t.meta2 AND a.meta3 = t.meta3 ), with_wh_mix AS ( SELECT j.*, tot.day_total_options, tot.day_total_combos, COALESCE(j.actual_options / NULLIF(tot.day_total_options, 0), 0) AS alloc_mix_pct, CASE WHEN j.category IN (\'TROUSERS\', \'JEANS\') THEN COALESCE(wp.warehouse_mix_pct, wf.warehouse_mix_pct, 0) WHEN j.store_zone IS NOT NULL THEN COALESCE(wp.warehouse_mix_pct, 0) ELSE COALESCE(wa.warehouse_mix_pct, 0) END AS raw_warehouse_mix_pct FROM joined_all j LEFT JOIN alloc_totals tot ON j.branch_code = tot.branch_code AND j.order_date = tot.order_date LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wp ON wp.scope = j.store_zone AND j.category = wp.category AND j.style = wp.style AND j.meta1 = wp.meta1 AND j.meta2 = wp.meta2 AND j.meta3 = wp.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wf ON wf.scope = j.other_zone AND j.category = wf.category AND j.style = wf.style AND j.meta1 = wf.meta1 AND j.meta2 = wf.meta2 AND j.meta3 = wf.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix wa ON wa.scope = \'ALL\' AND j.category = wa.category AND j.style = wa.style AND j.meta1 = wa.meta1 AND j.meta2 = wa.meta2 AND j.meta3 = wa.meta3 ), scored AS ( SELECT *, CASE WHEN sales_mix_target_pct > 0 AND raw_warehouse_mix_pct = 0 THEN \'Yes\' ELSE \'No\' END AS warehouse_constrained_flag, LEAST(sales_mix_target_pct, CASE WHEN raw_warehouse_mix_pct > 0 THEN sales_mix_target_pct ELSE 0 END) AS achievable_target_pct FROM with_wh_mix ), with_deviation AS ( SELECT *, ABS(alloc_mix_pct - achievable_target_pct) AS mix_deviation FROM scored ), day_rollup AS ( SELECT branch_code, order_date, SUM(mix_deviation * achievable_target_pct) / NULLIF(SUM(achievable_target_pct), 0) AS weighted_mix_deviation, COUNT_IF(warehouse_constrained_flag = \'Yes\') AS combos_warehouse_constrained FROM with_deviation GROUP BY branch_code, order_date ) SELECT sc.*, dr.weighted_mix_deviation, dr.combos_warehouse_constrained, CASE WHEN dr.combos_warehouse_constrained > 0 THEN \'Yes\' ELSE \'No\' END AS is_batch_warehouse_constrained, CASE WHEN sc.day_total_options < 3 THEN \'Insufficient Volume\' WHEN dr.weighted_mix_deviation IS NULL THEN \'No Data\' WHEN dr.weighted_mix_deviation <= 0.15 THEN \'Perfect\' WHEN dr.weighted_mix_deviation <= 0.30 THEN \'Okay\' ELSE \'Poor\' END AS mix_score FROM with_deviation sc LEFT JOIN day_rollup dr ON sc.branch_code = dr.branch_code AND sc.order_date = dr.order_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            